def find_path(graph, start, goal):
    explored = set()  # Set to keep track of already explored nodes
    path_stack = [(start, [start])]  # Stack for DFS, stores (current node, path from start to current node)

    while path_stack:
        (current_node, path) = path_stack.pop()
        if current_node not in explored:
            neighbors = graph.get(current_node, [])
            if goal in neighbors:
                return path + [goal]  # Goal found, add it to the path
            explored.add(current_node)
            for neighbor in neighbors:
                path_stack.append((neighbor, path + [neighbor]))  # Add neighbors to the stack

    return None  # Return None if goal is unreachable
