def find_path(graph, start, goal):
    # Initialize open and closed sets
    open_set = {start}
    closed_set = set()

    # Initialize parent dictionary
    parents = {start: None}

    # Initialize the g_score dictionary
    # g_score[start] is the cost from start along the path to start
    g_score = {start: 0}

    # Initialize f_score dictionary
    # f_score[start] is the cost from start along the path to start + the heuristic cost from start to goal
    f_score = {start: heuristic(start, goal)}

    while open_set:
        # Choose the node with the lowest f_score
        current = min(open_set, key=lambda node: f_score[node])

        if current == goal:
            # Goal has been reached, reconstruct the path
            path = []
            while current:
                path.append(current)
                current = parents[current]
            return path[::-1]  # Return the path in the correct order

        open_set.remove(current)
        closed_set.add(current)

        # Explore each neighbor of the current node
        for neighbor in graph[current]:
            if neighbor in closed_set:
                continue  # Skip already visited nodes

            tentative_g_score = g_score[current] + 1  # Assuming each step costs 1

            if neighbor not in open_set:
                open_set.add(neighbor)
            elif tentative_g_score >= g_score[neighbor]:
                continue  # This path is not better than previous one, skip

            parents[neighbor] = current
            g_score[neighbor] = tentative_g_score
            f_score[neighbor] = g_score[neighbor] + heuristic(neighbor, goal)

    # If the loop completes without finding a path
    return None

# Helper function to calculate the heuristic (e.g., Manhattan distance for a grid)
def heuristic(a, b):
    (x1, y1) = a
    (x2, y2) = b
    return abs(x1 - x2) + abs(y1 - y2)
