def find_path(graph, start, goal):
    queue = [(start, [start])]
    while queue:
        (vertex, path) = queue.pop(0)
        for next_node in graph[vertex] - set(path):
            if next_node == goal:
                return path + [goal]
            else:
                queue.append((next_node, path + [next_node]))
    return None
